<?php
use App\Actions\SaveListing;
use App\Livewire\AdminComponent;
use App\Models\Listing;
use Illuminate\Support\Str;
use Livewire\Attributes\Layout;
use Livewire\Attributes\Locked;

new #[Layout('layouts::admin')] class extends AdminComponent {
    #[Locked] public ?int $recordId=null;
    public array $form=['title'=>'','slug'=>'','kind'=>'property','category'=>'sale','property_type'=>'house','location'=>'','address'=>'','summary'=>'','description'=>'','bedrooms'=>0,'bathrooms'=>0,'guest_capacity'=>null,'area_sqm'=>null,'price'=>'','currency'=>'NGN','price_period'=>null,'min_nights'=>1,'max_nights'=>90,'amenities_text'=>'','cover_asset'=>'','video_url'=>'','status'=>'draft','featured'=>false,'is_demo'=>false];
    public function mount(?string $slug=null):void {
        if($slug){$listing=Listing::where('slug',$slug)->firstOrFail();$this->recordId=$listing->id;foreach(array_keys($this->form) as $key){if(!in_array($key,['price','amenities_text']))$this->form[$key]=$listing->$key;}$this->form['price']=$listing->price_minor===null?'':number_format($listing->price_minor/100,2,'.','');$this->form['amenities_text']=implode("\n",$listing->amenities??[]);}
        elseif(request()->query('kind')==='stay'){$this->form['kind']='stay';$this->form['category']='stay';$this->form['property_type']='apartment';$this->form['guest_capacity']=2;$this->form['price_period']='night';}
    }
    public function updatedFormTitle():void{if(!$this->recordId)$this->form['slug']=Str::slug($this->form['title']);}
    public function updatedFormKind():void{$this->form['category']=$this->form['kind']==='stay'?'stay':'sale';$this->form['price_period']=$this->form['kind']==='stay'?'night':null;if($this->form['kind']==='stay'&&!$this->form['guest_capacity'])$this->form['guest_capacity']=2;}
    public function save():void{$listing=app(SaveListing::class)->handle($this->form,$this->recordId?Listing::findOrFail($this->recordId):null);session()->flash('status','Space saved.');if(!$this->recordId)$this->redirectRoute('admin.listings.edit',['slug'=>$listing->slug]);}
};
?>
<div><header class="admin-page-heading"><div><a class="text-link" href="{{ route('admin.listings') }}">← All spaces</a><h1>{{ $recordId?'Edit your space':'A new space' }}</h1><p>Save a draft, add photographs, then publish when the details are ready.</p></div><span class="status-pill">{{ ucfirst($form['status']) }}</span></header>@if(session('status'))<p class="admin-flash" role="status">{{ session('status') }}</p>@endif @if($errors->any())<div class="form-errors" role="alert">@foreach($errors->all() as $error)<p>{{ $error }}</p>@endforeach</div>@endif<form wire:submit="save" class="admin-editor-form"><section class="admin-panel"><h2>The essentials</h2><div class="form-pair"><label>Listing title<input wire:model.live.debounce.300ms="form.title" maxlength="160" required></label><label>URL slug<input wire:model="form.slug" maxlength="180" required></label></div><div class="form-triple"><label>Space kind<select wire:model.live="form.kind"><option value="property">Property</option><option value="stay">Furnished stay</option></select></label><label>Category<select wire:model="form.category">@if($form['kind']==='stay')<option value="stay">Stay</option>@else<option value="sale">For sale</option><option value="rent">For rent</option><option value="investment">Investment</option>@endif</select></label><label>Property type<select wire:model="form.property_type">@foreach(config('grei.property_types') as $key=>$label)<option value="{{ $key }}">{{ $label }}</option>@endforeach</select></label></div><div class="form-pair"><label>Location / district<input wire:model="form.location" maxlength="100" required></label><label>Address <small>(optional)</small><input wire:model="form.address" maxlength="255"></label></div><label>Short introduction<textarea wire:model="form.summary" rows="2" maxlength="600"></textarea></label><label>Full description<textarea wire:model="form.description" rows="7" maxlength="20000"></textarea></label></section><section class="admin-panel"><h2>The details</h2><div class="form-triple"><label>Bedrooms<input type="number" wire:model="form.bedrooms" min="0" max="50"></label><label>Bathrooms<input type="number" wire:model="form.bathrooms" min="0" max="50"></label><label>Floor area (m²)<input type="number" wire:model="form.area_sqm" min="0" step="0.01"></label></div><div class="form-triple"><label>Price <small>(leave empty for enquiry)</small><input type="number" wire:model="form.price" min="0" step="0.01"></label><label>Currency<select wire:model="form.currency">@foreach(config('grei.currencies') as $code)<option value="{{ $code }}">{{ $code }}</option>@endforeach</select></label><label>Price period<select wire:model="form.price_period"><option value="">One-time price</option><option value="night">Per night</option><option value="month">Per month</option><option value="year">Per year</option></select></label></div>@if($form['kind']==='stay')<div class="form-triple"><label>Guest capacity<input type="number" wire:model="form.guest_capacity" min="1" max="50"></label><label>Minimum nights<input type="number" wire:model="form.min_nights" min="1" max="365"></label><label>Maximum nights<input type="number" wire:model="form.max_nights" min="1" max="365"></label></div>@endif<label>Amenities <small>(one per line)</small><textarea wire:model="form.amenities_text" rows="6" placeholder="Wi-Fi&#10;Parking&#10;Equipped kitchen"></textarea></label><label>YouTube / Vimeo tour <small>(HTTPS URL, optional)</small><input type="url" wire:model="form.video_url" placeholder="https://…"></label></section><section class="admin-panel"><h2>Publication</h2><div class="form-pair"><label>Status<select wire:model="form.status"><option value="draft">Draft — private</option><option value="published">Published — public</option></select></label><label class="admin-check"><input type="checkbox" wire:model="form.featured">Feature on the homepage</label></div><label class="admin-check"><input type="checkbox" wire:model.live="form.is_demo">This is illustrative demo content</label>@if($form['is_demo'])<label>Concept cover image<select wire:model="form.cover_asset"><option value="">Courtyard exterior</option><option value="assets/courtyard-exterior.webp">Courtyard exterior</option><option value="assets/city-apartment.webp">City apartment</option><option value="assets/courtyard-residence.webp">Coastal living</option><option value="assets/slow-morning.webp">Slow morning bedroom</option></select></label><p class="detail-caption">Demo content is labelled publicly and hidden when GREI_SHOW_DEMO is disabled.</p>@endif<button class="solid-button" type="submit" wire:loading.attr="disabled">Save space<x-grei.icon name="check" /></button></section></form>@if($recordId)<livewire:admin.media-manager type="listing" :record-id="$recordId" />@if($form['kind']==='stay')<livewire:admin.availability :listing-id="$recordId" />@endif @endif</div>
